from numpy import array


def remplir_m(m, n):
    for l in range(n):
        m[l, c] = l + 1
        m[l, l * 2] = l + 1
        for c in range(1, l * 2):
            if c <= l:
                m[l, c] = m[l, c - 1] + 1
            else:
                m[l, c] = m[l, c - 1] - 1
    print(m)


# pp
n = 6
m = array(([int()] * n) * n)
remplir_m(m, n)

